import 'package:flutter/material.dart';
import '../../services/api.dart';
class PublicBookingScreen extends StatefulWidget{const PublicBookingScreen({super.key,required this.api});final ApiClient api;@override State<PublicBookingScreen>createState()=>_PublicBookingScreenState();}
class _PublicBookingScreenState extends State<PublicBookingScreen>{final login=TextEditingController();dynamic ctx;String? error;Future<void>load()async{try{ctx=await widget.api.get('/public/booking/${login.text.trim()}');error=null;}catch(e){error='$e';}if(mounted)setState((){});}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Text('Agendamento público',style:Theme.of(c).textTheme.headlineSmall),TextField(controller:login,decoration:const InputDecoration(labelText:'Login público da barbearia')),FilledButton(onPressed:load,child:const Text('Abrir catálogo público')),if(error!=null)Text(error!),if(ctx!=null)...[Text('${ctx['owner']['shop_name']}',style:Theme.of(c).textTheme.titleLarge),for(final b in (ctx['barbers']as List))ListTile(leading:const Icon(Icons.content_cut),title:Text('${b['name']}'),subtitle:Text('${b['work_start']}–${b['work_end']}')),const Text('O link público consulta a mesma disponibilidade da API; o envio final é feito pela rota POST /public/appointments.')]]);}
